// Deterministic mock barcode component to ensure zero runtime randomness
const Barcode: React.FC<{ height: number; width: number; color: string }> = ({ height, width, color }) => {
  const bars = [1, 3, 1, 2, 4, 1, 3, 2, 1, 1, 4, 2, 1, 3, 1, 2, 1, 4, 2, 1, 3, 1, 2];
  return (
    <div style={{ display: "flex", flexDirection: "row", alignItems: "stretch", height, width, transition: "none" }}>
      {bars.map((weight, i) => (
        <div
          key={i}
          style={{
            flex: weight,
            backgroundColor: i % 2 === 0 ? color : "transparent",
            marginLeft: i === 0 ? 0 : 1,
            transition: "none",
          }}
        />
      ))}
    </div>
  );
};

