export const BoardingPassTransformation: React.FC<BoardingPassTransformationProps> = ({
  backgroundColor = "#080710",
  transparentBackground = true,
  durationInSeconds = 8,
  flightNumber = "AA 100",
  departureCode = "JFK",
  arrivalCode = "LHR",
  departureCity = "NEW YORK",
  arrivalCity = "LONDON",
  date = "24 MAY",
  boardingTime = "08:40",
  economySeat = "32B",
  premiumSeat = "1A",
  primaryColor = "#0D1B2A",
  goldColor = "#D4AF37",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Resolve Background Color Transparency
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Boarding Pass Proportional Sizing
  const cardWidth = Math.round(width * 0.46);
  const cardHeight = Math.round(cardWidth * 0.42);
  const R = 18; 
  const BR = 14; 
  const PX = Math.round(cardWidth * 0.70); 

  // Mathematically computed ticket SVG path supporting physical ticket bites
  const ticketPath = `M ${R} 0 
                      L ${PX - BR} 0 
                      A ${BR} ${BR} 0 0 1 ${PX + BR} 0 
                      L ${cardWidth - R} 0 
                      A ${R} ${R} 0 0 1 ${cardWidth} ${R} 
                      L ${cardWidth} ${cardHeight - R} 
                      A ${R} ${R} 0 0 1 ${cardWidth - R} ${cardHeight} 
                      L ${PX + BR} ${cardHeight} 
                      A ${BR} ${BR} 0 0 1 ${PX - BR} ${cardHeight} 
                      L ${R} ${cardHeight} 
                      A ${R} ${R} 0 0 1 0 ${cardHeight - R} 
                      L 0 ${R} 
                      A ${R} ${R} 0 0 1 ${R} 0 
                      Z`;

  const clipPathId = "ticket-clip-path";

  // TIMING SEGMENTS
  const fEntranceEnd = fps * 1.2;
  const fFlipStart = fps * 3.2;
  const fFlipEnd = fps * 4.2;
  const fShimmerStart = fFlipEnd;
  const fShimmerEnd = fShimmerStart + (fps * 1.0);
  const fLineStart = fps * 6.0;
  const fLineEnd = fps * 7.0;
  const fExitStart = durationInFrames - (fps * 0.6);

  // 1. Entrance Interpolation (Float-In)
  const tEntrance = interpolate(frame, [0, fEntranceEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });
  const cardScale = interpolate(tEntrance, [0, 1], [0.75, 1.0]);
  const translateY = interpolate(tEntrance, [0, 1], [height * 0.35, 0]);
  const cardOpacity = interpolate(tEntrance, [0, 1], [0, 1]);

  // 2. Ambient Floating Mechanics (Hover and Tilt)
  const hoverOffset = Math.sin(frame / 15) * 8;
  const wiggleOffset = Math.cos(frame / 20) * 0.6;
  const baseTilt = interpolate(tEntrance, [0, 1], [-15, -4]);
  const currentTilt = baseTilt + wiggleOffset;

  // 3. Horizontal 3D Card Flip
  const tFlip = interpolate(frame, [fFlipStart, fFlipEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.quad),
  });
  const rotateYVal = interpolate(tFlip, [0, 1], [0, 180]);
  const isPremiumFace = rotateYVal >= 90;

  // 4. Premium Light Catch Shimmer
  const shimmerOffset = interpolate(frame, [fShimmerStart, fShimmerEnd], [-cardWidth * 1.2, cardWidth * 1.2], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 5. Signature Gold Underline Animation
  const tLine = interpolate(frame, [fLineStart, fLineEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.quad),
  });

  // 6. Global Fade Out
  const globalOpacity = interpolate(frame, [fExitStart, durationInFrames], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFont,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      {/* Clip path defs */}
      <svg width="0" height="0" style={{ position: "absolute" }}>
        <defs>
          <clipPath id={clipPathId}>
            <path d={ticketPath} />
          </clipPath>
        </defs>
      </svg>

      {/* Boarding Pass Wrapper with Perspective context */}
      <div
        style={{
          perspective: "1800px",
          width: cardWidth,
          height: cardHeight,
          opacity: cardOpacity * globalOpacity,
          transform: `scale(${cardScale}) translateY(${translateY + hoverOffset}px)`,
          transition: "none",
        }}
      >
        <div
          style={{
            position: "relative",
            width: "100%",
            height: "100%",
            transformStyle: "preserve-3d",
            transform: `rotateY(${rotateYVal}deg) rotateZ(${currentTilt}deg)`,
            transition: "none",
          }}
        >
          {/* Card Faces */}
          {!isPremiumFace && (
            <CardFace
              isPremium={false}
              width={cardWidth}
              height={cardHeight}
              ticketPath={ticketPath}
              clipPathId={clipPathId}
              primaryColor={primaryColor}
              goldColor={goldColor}
              flightNumber={flightNumber}
              departureCode={departureCode}
              arrivalCode={arrivalCode}
              departureCity={departureCity}
              arrivalCity={arrivalCity}
              date={date}
              boardingTime={boardingTime}
              economySeat={economySeat}
              premiumSeat={premiumSeat}
              shimmerOffset={shimmerOffset}
            />
          )}

          {isPremiumFace && (
            <CardFace
              isPremium={true}
              width={cardWidth}
              height={cardHeight}
              ticketPath={ticketPath}
              clipPathId={clipPathId}
              primaryColor={primaryColor}
              goldColor={goldColor}
              flightNumber={flightNumber}
              departureCode={departureCode}
              arrivalCode={arrivalCode}
              departureCity={departureCity}
              arrivalCity={arrivalCity}
              date={date}
              boardingTime={boardingTime}
              economySeat={economySeat}
              premiumSeat={premiumSeat}
              shimmerOffset={shimmerOffset}
            />
          )}
        </div>
      </div>

      {/* Signature Metallic Underline */}
      <div
        style={{
          position: "absolute",
          top: height / 2 + cardHeight / 2 + 55,
          left: width / 2 - (cardWidth * 1.05) / 2,
          width: cardWidth * 1.05,
          height: 3,
          background: "linear-gradient(90deg, transparent, #BF953F 20%, #FCF6BA 50%, #B38728 80%, transparent)",
          transform: `scaleX(${tLine})`,
          transformOrigin: "left",
          opacity: cardOpacity * globalOpacity,
          borderRadius: 2,
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default BoardingPassTransformation;